#include <cstddef>
#include <iostream>
#include <string>

int main() {
    const std::string file = "report_2024_final.txt";
    const std::size_t first = file.find('_');
    const std::size_t second = file.find('_', first + 1);
    std::cout << "First _ at: " << first << '\n';
    std::cout << "Second _ at: " << second << '\n';
    std::cout << "Year: " << file.substr(first + 1, second - first - 1) << '\n';

    const std::size_t dot = file.rfind('.');
    std::cout << "Extension: " << file.substr(dot + 1) << '\n';

    std::cout << std::boolalpha;
    std::cout << "Has draft: " << (file.find("draft") != std::string::npos) << '\n';
    std::cout << "Starts with report: " << (file.rfind("report", 0) == 0) << '\n';
    return 0;
}

