#include <cstddef>
#include <iostream>
#include <string>

int main() {
    const std::string email = "grace.hopper@navy.mil";
    const std::size_t dot = email.find('.');
    const std::size_t at = email.find('@', dot + 1);
    std::cout << "Dot at: " << dot << '\n';
    std::cout << "@ at: " << at << '\n';
    std::cout << "First: " << email.substr(0, dot) << '\n';
    std::cout << "Last: " << email.substr(dot + 1, at - dot - 1) << '\n';

    const std::size_t lastDot = email.rfind('.');
    std::cout << "Domain: " << email.substr(lastDot + 1) << '\n';

    std::cout << std::boolalpha;
    std::cout << "Has army: " << (email.find("army") != std::string::npos) << '\n';
    std::cout << "Starts with grace: " << (email.rfind("grace", 0) == 0) << '\n';
    return 0;
}

