#include <iomanip>
#include <iostream>
#include <string>

int main() {
    const std::string apple = "apple";
    const std::string banana = "banana";
    const std::string zebra = "Zebra";
    const std::string capitalApple = "Apple";
    std::cout << std::boolalpha;
    std::cout << "apple < banana: " << (apple < banana) << '\n';
    std::cout << "Zebra < apple: " << (zebra < apple) << '\n';
    std::cout << "apple == Apple: " << (apple == capitalApple) << '\n';

    const int count = std::stoi("42") + 8;
    const double price = std::stod("3.75");
    std::cout << std::fixed << std::setprecision(1);
    std::cout << "Count: " << count << '\n';
    std::cout << "Doubled: " << price * 2 << '\n';

    const std::string label = "Total: " + std::to_string(count);
    std::cout << label << '\n';
    std::cout << std::to_string(3.5) << '\n';
    return 0;
}

