    const std::string lower = "alice";
    const std::string upper = "Alice";
    std::cout << std::boolalpha;
    std::cout << "alice == Alice: " << (lower == upper) << '\n';
    std::cout << "alice < Alice: " << (lower < upper) << '\n';
    std::cout << "Alice < alice: " << (upper < lower) << '\n';

    const int year = std::stoi("1999");
    const double rate = std::stod("0.25");
    std::cout << std::fixed << std::setprecision(1);
    std::cout << "Year: " << year << '\n';
    std::cout << "Times 4: " << rate * 4 << '\n';

    const std::string label = "Year " + std::to_string(year + 1);
    std::cout << label << '\n';
    std::cout << std::to_string(0.25) << '\n';
    return 0;
}
